import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'api_client.dart';
import 'package:qr_flutter/qr_flutter.dart';
import 'package:url_launcher/url_launcher.dart';

void main() => runApp(const DiabetaApp());
class DiabetaApp extends StatelessWidget { const DiabetaApp({super.key}); @override Widget build(BuildContext c) => MaterialApp(debugShowCheckedModeBanner: false, title: 'Diabeta', theme: ThemeData(useMaterial3: true, colorSchemeSeed: Colors.blue), home: const AuthGate()); }
class AuthGate extends StatefulWidget { const AuthGate({super.key}); @override State<AuthGate> createState() => _AuthGateState(); }
class _AuthGateState extends State<AuthGate> { bool ready = false; @override void initState() { super.initState(); _check(); } Future<void> _check() async { final p = await SharedPreferences.getInstance(); if (mounted) setState(() => ready = p.getString('token') != null); } void loggedIn() { setState(() => ready = true); } @override Widget build(BuildContext c) => ready ? Dashboard(onLogout: () async { final p = await SharedPreferences.getInstance(); await p.remove('token'); if (mounted) setState(() => ready = false); }) : Login(onLogin: loggedIn); }
class Login extends StatefulWidget { final VoidCallback onLogin; const Login({super.key, required this.onLogin}); @override State<Login> createState() => _LoginState(); }
class _LoginState extends State<Login> { final email = TextEditingController(); final pass = TextEditingController(); final api = ApiClient(); String error = ''; bool register = false; Future<void> submit() async { try { final r = await api.post(register ? '/auth/register' : '/auth/login', {'email': email.text.trim(), 'password': pass.text, 'firstName': 'Usuario'}); final p = await SharedPreferences.getInstance(); await p.setString('token', r['accessToken'].toString()); widget.onLogin(); } catch (_) { if (mounted) setState(() => error = 'No se pudo iniciar sesión. Comprueba los datos.'); } } @override Widget build(BuildContext c) => Scaffold(body: Center(child: SingleChildScrollView(padding: const EdgeInsets.all(24), child: Column(children: [const Icon(Icons.monitor_heart, size: 72), Text('Diabeta', style: Theme.of(c).textTheme.headlineMedium), Text(register ? 'Crear cuenta' : 'Iniciar sesión'), TextField(controller: email, decoration: const InputDecoration(labelText: 'Email')), TextField(controller: pass, obscureText: true, decoration: const InputDecoration(labelText: 'Contraseña')), if (error.isNotEmpty) Text(error), FilledButton(onPressed: submit, child: Text(register ? 'Crear cuenta' : 'Entrar')), TextButton(onPressed: () => setState(() => register = !register), child: Text(register ? 'Ya tengo cuenta' : 'Crear una cuenta'))])))); }
class Dashboard extends StatefulWidget { final Future<void> Function() onLogout; const Dashboard({super.key, required this.onLogout}); @override State<Dashboard> createState() => _DashboardState(); }
class _DashboardState extends State<Dashboard> { final api = ApiClient(); List<dynamic> glucose = []; List<dynamic> insulin = []; String status = 'Cargando...';
Future<void> load() async { try { final g = await api.getList('/glucose'); final i = await api.getList('/insulin'); if (mounted) setState(() { glucose = g; insulin = i; status = 'Datos sincronizados'; }); } catch (_) { if (mounted) setState(() => status = 'No se han podido cargar los datos.'); } }
@override void initState() { super.initState(); load(); }
@override Widget build(BuildContext c) { final latest = glucose.isEmpty ? '--' : glucose.first['value'].toString(); return Scaffold(appBar: AppBar(title: const Text('Diabeta'), actions: [IconButton(onPressed: widget.onLogout, icon: const Icon(Icons.logout))]), body: RefreshIndicator(onRefresh: load, child: ListView(padding: const EdgeInsets.all(20), children: [Text('Glucosa actual'), Text('$latest mg/dL', style: Theme.of(c).textTheme.displaySmall), Text(status), Card(child: ListTile(title: const Text('Registrar glucosa'), onTap: () => _recordGlucose(c))), Card(child: ListTile(title: const Text('Registrar insulina'), onTap: () => _recordInsulin(c))), Card(child: ListTile(title: const Text('Tarjeta médica QR'), onTap: () => _medical(c))), Card(child: ListTile(title: const Text('SOS'), onTap: () => _sos(c))), Text('Registros: ${glucose.length} glucosa · ${insulin.length} insulina')]))); }
Future<void> _recordGlucose(BuildContext c) async { final x = TextEditingController(); await showDialog(context: c, builder: (_) => AlertDialog(title: const Text('Glucosa'), content: TextField(controller: x, keyboardType: TextInputType.number, decoration: const InputDecoration(hintText: 'mg/dL')), actions: [TextButton(onPressed: () => Navigator.pop(c), child: const Text('Cancelar')), TextButton(onPressed: () async { final v = double.tryParse(x.text); if (v != null) await api.post('/glucose', {'value': v, 'recordedAt': DateTime.now().toUtc().toIso8601String()}); if (c.mounted) Navigator.pop(c); }, child: const Text('Guardar'))])); await load(); }
Future<void> _recordInsulin(BuildContext c) async { final x = TextEditingController(); await showDialog(context: c, builder: (_) => AlertDialog(title: const Text('Insulina rápida'), content: TextField(controller: x, keyboardType: TextInputType.number, decoration: const InputDecoration(hintText: 'unidades')), actions: [TextButton(onPressed: () => Navigator.pop(c), child: const Text('Cancelar')), TextButton(onPressed: () async { final v = double.tryParse(x.text); if (v != null) await api.post('/insulin', {'units': v, 'insulinType': 'rapid', 'recordedAt': DateTime.now().toUtc().toIso8601String()}); if (c.mounted) Navigator.pop(c); }, child: const Text('Guardar'))])); await load(); }
Future<void> _medical(BuildContext c) async { try { final m = await api.getMap('/medical'); if (!c.mounted) return; showDialog(context: c, builder: (_) => AlertDialog(title: const Text('Tarjeta médica'), content: SizedBox(width: 260, child: Column(mainAxisSize: MainAxisSize.min, children: [QrImageView(data: 'diabeta://medical/${m['qrToken'] ?? ''}', size: 200), const Text('Código QR privado para la tarjeta médica de emergencia.')]))); } catch (_) { if (c.mounted) showDialog(context: c, builder: (_) => const AlertDialog(title: Text('Tarjeta médica'), content: Text('Primero completa tu perfil médico.'))); } }
void _sos(BuildContext c) => showDialog(context: c, builder: (_) => AlertDialog(title: const Text('SOS'), content: const Text('Si existe una emergencia, llama a los servicios de emergencia. La app no realiza una alerta automática.'), actions: [TextButton(onPressed: () => Navigator.pop(c), child: const Text('Cerrar')), FilledButton.icon(onPressed: () async { await launchUrl(Uri(scheme: 'tel', path: '112')); }, icon: const Icon(Icons.phone), label: const Text('Llamar 112'))])); }